<script setup lang="ts">import {ref} from 'vue';import ScreenPanel from './ScreenPanel.vue';import ThreeScene from '@/components/three/ThreeScene.vue';import {buildingsApi} from '@/api/buildings';import type {Building,Device,HourlySimulationPoint,Site,SiteOverview} from '@/types';defineProps<{site:Site;overview:SiteOverview|null;buildings:Building[];hourly?:HourlySimulationPoint[]}>();const devices=ref<Device[]>([]);async function drill(b:Building){try{devices.value=await buildingsApi.devices(b.id)}catch{devices.value=[]}}</script>
<template><ScreenPanel title="空间业务总览" link="/3d"><div class="spatial-stats"><span>建筑 <b>{{overview?.building_count??'--'}}</b></span><span>设备 <b>{{overview?.device_count??'--'}}</b></span><span>能源系统 <b>{{overview?.energy_system_count??'--'}}</b></span><span>计量点 <b>{{overview?.metering_point_count??'--'}}</b></span></div><ThreeScene :site="site" :buildings="buildings" :devices="devices" :hourly="hourly" compact @building="drill"/></ScreenPanel></template>
